class Command(BaseCommand):
    """Populate the BattleTech product line (idempotent)."""

    help = 'Populates BattleTech products (114 SKUs; BT-001/002/005/009/020 retired, BT-098-119 added).'

    def handle(self, *args, **options):
        category, _ = Category.objects.get_or_create(
            slug='battletech',
            defaults={'name': 'Battletech'},
        )

        catalyst, _ = Retailer.objects.get_or_create(
            slug='catalyst-game-labs',
            defaults={
                'name': 'Catalyst Game Labs',
                'website': 'https://store.catalystgamelabs.com',
                'country': 'US',
                'is_active': True,
                'is_uk': False,
            },
        )

        products_created = 0
        products_updated = 0
        prices_created = 0
        prices_updated = 0

        for slug, gw_sku, name, msrp, image_url, product_url, ebay_search_name in PRODUCTS:
            product, created = Product.objects.update_or_create(
                slug=slug,
                defaults={
                    'gw_sku': gw_sku,
                    'name': name,
                    'category': category,
                    'msrp': msrp,
                    'image_url': image_url,
                    'gw_url': product_url,
                    'ebay_search_name': ebay_search_name,
                    # "&" is a common word in BattleTech ForcePack/BattleMat names
                    # (e.g. "Battle & Fire Lances") -- without this, the eBay
                    # bundle-listing filter rejects every otherwise-valid result.
                    'ebay_allowed_title_words': '&',
                    'batch_tag': 'battletech',
                    'is_active': True,
                },
            )
            if created:
                products_created += 1
            else:
                products_updated += 1

            _, price_created = CurrentPrice.objects.update_or_create(
                product=product,
                retailer=catalyst,
                defaults={
                    'price': msrp,
                    'url': product_url,
                    'in_stock': True,
                    'not_available': False,
                },
            )
            if price_created:
                prices_created += 1
            else:
                prices_updated += 1

        self.stdout.write(self.style.SUCCESS(
            f'Products: {products_created} created, {products_updated} updated.'
        ))
        self.stdout.write(self.style.SUCCESS(
            f'Catalyst Game Labs prices: {prices_created} created, {prices_updated} updated.'
        ))
